def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
    for token in chain:
        chain_dict[token].append(token)

    chain_dict = sorted(chain_dict.items())

    current = chain_dict[0]
    result = []

    while current:
        next_token = current[0]
        result.append(next_token)
        current = current[1:]

    return ','.join(result)

# Example usage:
# print(chain_follow(['yvf', 'boa']))  # Output: yvf, boa
